<template>
        <div class="layout-px-spacing bg-white"> 
          <div class="d-flex mb-4">
            <div class="ms-auto">
            <button
            class="btn btn-primary"
            data-bs-toggle="modal"
            data-bs-target="#budgetConsumption"
            >
            <i class="bi bi-plus-square"/>
          </button> 
            </div>
          </div>


                <div class="modal fade" id="budgetConsumption" tabindex="-1" role="dialog" aria-labelledby="editModalLabel" aria-hidden="true">
    <div class="modal-dialog modal-xl" role="document"> <!-- Changed to modal-xl and added scrollable -->
        <div class="modal-content"> <!-- Added min-height -->
            <div class="modal-header">
                <h5 class="modal-title" id="editModalLabel">FABRICATION PRODUCT REGISTRATION FORM</h5>
                <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close-form"></button>
            </div>
            <div class="modal-body">
              <div class="row">
                <div class="col">
                    <div class="form-label">Select Work Order Group</div>
                                    <Multiselect
  v-model="workOrderGroup"
  :options="workOrderGroups"
  :close-on-select="true"
  label="description"
  value-prop="id"
  placeholder="Select Group"  
  :searchable="true" 
/>    
                </div>
                <div class="col">
                    <div class="form-label">Select Parent Group</div>
                                                        <Multiselect
  v-model="workOrderItem"
  :options="workOrderItems"
  :close-on-select="true"
  label="name"
  value-prop="id"
  placeholder="Select Group"  
  :searchable="true" 
/>    
                </div>

                  <div class="col">
                    <div class="form-label">Select Fabrication Product </div>
            <Multiselect
  v-model="productItem"
  :options="productItems"
  :close-on-select="true"
  label="name"
  value-prop="id"
  placeholder="Select Group"  
  :searchable="true" 
/>   
                </div>
                
              </div>
  
        </div>
                          <div class="modal-footer">
                <button type="button" class="btn btn-secondary btn-sm" data-bs-dismiss="modal">Close</button>
                <button type="button" class="btn btn-success btn-sm" @click="submitProductItem()" :disabled="loading">
                  <span v-if="loading" v-html="loadingSpinner()"></span>
                  <span v-else>Save</span>
                </button>

              </div>
        </div>
            </div>
            
            </div>


                            <div class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="fabricationProducts" :columns="columns" :options="table_option">
                           
                            <template #actions="props">
                                
                                    <a href="javascript:;" 
                                       v-if="user_permissions.includes('can_edit_work_order')"
                                    class="edit me-3" @click="edit_row(props.row)">
                                           <i class="bi bi-pencil-square fs-5 text-primary"></i>
                                        </a>

                            </template>
                           <template #footer>
                               <div class="modal-footer">
                                   <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Close</button>
                                   <button type="button" class="btn btn-primary" @click="save_edit" :disabled="isSaving" >Save changes</button>
                               </div>
                           </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>
        </div>





</template>

<script setup>
    import { onMounted, ref,inject,watch } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Work Order' });
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const columns = [ 'sno','name','parent','actions'];

        const table_option = ref({
    perPage: 10,
    perPageValues: [5, 10, 20, 50],
    skin: 'table table-hover',
    columnsClasses: { actions: 'actions text-center' },
    pagination: { nav: 'scroll', chunk: 5 },
    texts: {
        count: 'Showing {from} to {to} of {count}',
        filter: '',
        filterPlaceholder: 'Search...',
        limit: 'Results:',
    },
    sortable: ['SNo', 'date_issued', 'fuel_issued'],
    sortIcon: {
        base: 'sort-icon-none',
        up: 'sort-icon-asc',
        down: 'sort-icon-desc',
    },
    resizableColumns: false,
    searchable: true,

});


       const user_permissions = JSON.parse(localStorage.getItem('user')).permissions

const props = defineProps({
    workOrderId: String
});

const loadingSpinner = inject('loadingSpinner')

const loading = ref(false)
const workOrderGroup = ref('')
const workOrderGroups = ref([])
const getWorkOrderGroups = async()=>{
  const response = await axiosInstance.get('work-order-groups')
  workOrderGroups.value = response.data
}

const workOrderItem = ref('')
const workOrderItems = ref([])
const getWorkOrderItems = async()=>{
  const response = await axiosInstance.get(`work-order-items?order_group_id=${workOrderGroup.value.id}`)
  workOrderItems.value = response.data
}

    watch(workOrderGroup, (newVal) => {
    if (newVal) {
       getWorkOrderItems()
    }
});

const productItems = ref([])
const productItem = ref('')
const getProductItems = async()=>{
  const response = await axiosInstance.get('items?category_id=5')
  productItems.value = response.data
}

const showError = inject('showError')
const showMessage = inject('showMessage')
const clearForm = ()=>{
  workOrderItem.value = '',
  productItem.value = '',
  workOrderGroup.value = '',
  document.getElementById('close-form').click()
}


const submitProductItem = async()=>{
  loading.value = true
  const payload = {
     order_group_id : workOrderItem.value.id,
     item_id : productItem.value.id,
     item : productItem.value.name,
     issuer_id : JSON.parse(localStorage.getItem('user')).id
  }
  try{
      const response = await axiosInstance.post('order-group-items',payload)
      showMessage('Data Saved!')
      clearForm()
  }catch(error){
    showError(error.message)
    console.log(error)
  }finally{
    loading.value = false;
  }

}

const fabricationProducts = ref([])
const getFabricationProducts = async()=>{
  const response = await axiosInstance.get('order-group-items')
  fabricationProducts.value = response.data.map((item,index)=>({
   ...item,
  sno : index+1
  }))
}

    onMounted(async() => {
      getWorkOrderGroups()    
      getProductItems() 
      getFabricationProducts()
    });
</script>

